create table retrieval_record (id bigint auto_increment primary key,retrieval_uuid varchar(36) not null,agent_run_id bigint not null,project_id bigint not null,document_uuid varchar(36) not null,document_version int not null,chunk_uuid varchar(36) not null,rank_no int not null,score decimal(10,6) not null,chunking_version varchar(64) not null,embedding_model varchar(128) not null,query_hash char(64) not null,rag_enabled tinyint not null,context_budget int not null,mock tinyint not null default 0,selected_at datetime not null default current_timestamp,unique key uk_retrieval_record_run_chunk (agent_run_id,chunk_uuid),key idx_retrieval_record_project_run (project_id,agent_run_id,rank_no));
